package com.andye.warmod.menu;import com.andye.warmod.block.entity.PhalanxBlockEntity;import com.andye.warmod.item.ModItems;import net.minecraft.core.BlockPos;import net.minecraft.server.level.ServerLevel;import net.minecraft.world.SimpleContainer;import net.minecraft.world.entity.player.*;import net.minecraft.world.inventory.*;import net.minecraft.world.item.ItemStack;import org.jspecify.annotations.Nullable;
public final class PhalanxMenu extends AbstractContainerMenu{private final BlockPos centre;private final @Nullable PhalanxBlockEntity turret;public PhalanxMenu(int id,Inventory inv,ModMenus.PhalanxOpeningData d){this(id,inv,inv.player.level().getBlockEntity(d.centre())instanceof PhalanxBlockEntity p?p:null,d.centre());}public PhalanxMenu(int id,Inventory inv,PhalanxBlockEntity p){this(id,inv,p,p.getBlockPos());}private PhalanxMenu(int id,Inventory inv,@Nullable PhalanxBlockEntity p,BlockPos centre){super(ModMenus.PHALANX,id);this.centre=centre;turret=p;var c=p==null?new SimpleContainer(2):p;checkContainerSize(c,2);addSlot(new Slot(c,0,44,46){@Override public boolean mayPlace(ItemStack s){return s.is(ModItems.ANTI_AIR_GUN_AMMO);}});addSlot(new Slot(c,1,116,46){@Override public boolean mayPlace(ItemStack s){return s.is(ModItems.ANTI_AIR_GUN_AMMO);}});addStandardInventorySlots(inv,10,134);}@Override public boolean stillValid(Player p){return turret!=null&&p.level()==turret.getLevel()&&p.distanceToSqr(net.minecraft.world.phys.Vec3.atCenterOf(centre))<=64;}@Override public ItemStack quickMoveStack(Player p,int index){Slot slot=getSlot(index);if(!slot.hasItem())return ItemStack.EMPTY;ItemStack stack=slot.getItem(),copy=stack.copy();if(index<2){if(!moveItemStackTo(stack,2,38,true))return ItemStack.EMPTY;}else if(stack.is(ModItems.ANTI_AIR_GUN_AMMO)){if(!moveItemStackTo(stack,0,2,false))return ItemStack.EMPTY;}else return ItemStack.EMPTY;if(stack.isEmpty())slot.setByPlayer(ItemStack.EMPTY);else slot.setChanged();return copy;}public @Nullable PhalanxBlockEntity turret(){return turret;}}
